function PlayerController:Init(character_, humanPrefabTF_, WhenPlayerMoveStateChangeds_ )
    KTool.SetActive(self.controller.gameObject, true)

    if isNull( character_) or isNull(character_.AnimationAdapter) then 
        printError("character_ or character_.AnimationAdapter is nil")
    end 

    self.customAnimationEvents  = KTool.GetComponent(humanPrefabTF_.gameObject, typeof(CustomAnimationEvents))
    self.rootMotion             = KTool.GetComponent(humanPrefabTF_.gameObject, typeof(RootMotion))
    assert( self.customAnimationEvents and self.rootMotion )


    ------ 绑定 animation clip event:
    self.OnWhenCallEvent_Effect = function( name )
        self:WhenCallEvent_Effect( name )
    end
    self.customAnimationEvents:OnEffect( "+", self.OnWhenCallEvent_Effect )

    self.playerState = PlayerState.Idle

    ---
    local params = KTool.GetComponent(self.controller.gameObject, typeof(LuaParameters))
    assert( params )

    -- 是否可以跑步
    self.canRun = LuaParametersReader.Read( params, "canRun", LuaParamType.Bool )

    -- 跑停
    self.hasRunStop = LuaParametersReader.Read( params, "hasRunStop", LuaParamType.Bool )
    self.runValue = LuaParametersReader.Read( params, "runValue", LuaParamType.Float )

    -- 180°转身
    self.hasTurnBack = LuaParametersReader.Read( params, "hasTurnBack", LuaParamType.Bool ) -- !! 现在也允许外部 (CreatePlayer) 修改变量了
    self.runTurnBackAngleThreshold = LuaParametersReader.Read( params, "runTurnBackAngleThreshold", LuaParamType.Float )
    self.runTurnBackDistanceThreshold = LuaParametersReader.Read( params, "runTurnBackDistanceThreshold", LuaParamType.Float )

    -- 小动作
    self.idleMotionInterval = LuaParametersReader.Read( params, "idleMotionInterval", LuaParamType.Float )

    -- 移动灵敏度
    self.forwardAxisSharpness = LuaParametersReader.Read( params, "forwardAxisSharpness", LuaParamType.Float )
    self.rotateTimeMax = LuaParametersReader.Read( params, "rotateTimeMax", LuaParamType.Float )

    -- 镜头的默认参数
    self.defaultYAxisValue = LuaParametersReader.Read( params, "defaultYAxisValue", LuaParamType.Float )
    self.defaultYAxisSpeed = LuaParametersReader.Read( params, "defaultYAxisSpeed", LuaParamType.Float )

    --------
    local moveScales_walk    = LuaParametersReader.Read( params, "moveScales_walk",   LuaParamType.Float ) -- rootMotion xz平面位移倍率; (walk) 推荐: 0.8
    local moveScales_run     = LuaParametersReader.Read( params, "moveScales_run",    LuaParamType.Float ) -- rootMotion xz平面位移倍率; (run) 推荐: 1.2

    self.rootMotionCustoms = RootMotionCustoms.New( self.rootMotion, moveScales_walk, moveScales_run, function()
        return (self.playerState == PlayerState.Move)
    end )


    -- ============ events ===========
    -- self.EventSetHumanHasTurnBack  = Events.AddListener(DreamSpaceStates.EventNames.SetHumanHasTurnBack, function( newHasTurnBack_ )
    --     --printError("-- SetHumanHasTurnBack")
    --     self.hasTurnBack = checkBool(newHasTurnBack_)
    -- end)


    -- =======================
    self._character = character_
    self._character.useRootMotionMove = true

    assert( type(WhenPlayerMoveStateChangeds_) == "table" )
    for _,func in pairs(WhenPlayerMoveStateChangeds_) do 
        assert( type(func) == "function" )
        table.insert( self.WhenPlayerMoveStateChangeds, func )
    end

    -- 主动触发一次 callback
    self:UpdateFootStepState( 0 )

end



function PlayerController:DetachCharacter()
    self._character = nil
end



function PlayerController:SetCharacterFSM()
    if self._fsm == nil then
        local fsm = FSM()
        local idleState = fsm:AddState(PlayerState.Idle)
        local moveState = fsm:AddState(PlayerState.Move)
        local switchState = fsm:AddState(PlayerState.Switch)
        local attackState = fsm:AddState(PlayerState.Attack)
        fsm.currentState = idleState

        idleState.onEnterState = function(fsm, selfState, fromState, param)
            self:IdleEnterState(fsm, selfState, fromState, param)
        end
        
        idleState.onUpdate = function(fsm, selfState, deltaTime)
            self:IdleUpdate(fsm, selfState, deltaTime)
        end
        
        moveState.onEnterState = function(fsm, selfState, fromState, param)
            self:MoveEnterState(fsm, selfState, fromState, param)
        end
    
        moveState.onUpdate = function(fsm, selfState, deltaTime)
            self:MoveUpdate(fsm, selfState, deltaTime)
        end
        
        moveState.onExitState = function(fsm, selfState, toState, param)
            self:MoveExitState(fsm, selfState, toState, param)
        end
        
        moveState.onCanTransitionTo = function(fsm, selfState, toState, param)
            return self:MoveCanTransitionTo(fsm, selfState, toState, param)
        end
        
        switchState.onEnterState = function(fsm, selfState, fromState, param)
            self:SwitchEnterState(fsm, selfState, fromState, param)
        end
        
        switchState.onUpdate = function(fsm, selfState, deltaTime)
            self:SwitchUpdate(fsm, selfState, deltaTime)
        end

        switchState.onCanTransitionTo = function(fsm, selfState, toState, param)
            return self:SwitchCanTransitionTo(fsm, selfState, toState, param)
        end

        attackState.onEnterState = function(fsm, selfState, fromState, param)
            self:AttackEnterState(fsm, selfState, fromState, param)
        end

        attackState.onUpdate = function(fsm, selfState, deltaTime)
            self:AttackUpdate(fsm, selfState, deltaTime)
        end

        attackState.onCanTransitionTo = function(fsm, selfState, toState, param)
            return self:AttackCanTransitionTo(fsm, selfState, toState, param)
        end

        self._fsm = fsm
    end
    self._character:SetFSM(self._fsm)
end


function PlayerController:ResetCharacterFSM()
    self._character:SetFSM(nil)
end


function PlayerController:MoveStart()
    self._character.FSM:TryTransitionTo(PlayerState.Move)
    self._hasMoveInput = true
end


function PlayerController:Move(moveInput)
    if self._character.FSM.currentState.stateId ~= PlayerState.Move then
        self:MoveStart()
        return
    end
    self._lastMoveInput = self._moveInput
    self._moveInput = self.canRun and moveInput or moveInput * (self.runValue - 0.01)
    self._moveDir = self._moveInput.normalized
end


function PlayerController:MoveEnd()
    self._character.FSM:TryTransitionTo(PlayerState.Idle)
    self._hasMoveInput = false
end


function PlayerController:SwitchIn(roleMoveState, rotate)
    self._switchInOrOut = true
    self._character.FSM:TryTransitionTo(PlayerState.Switch, self._switchInOrOut)
end


function PlayerController:SwitchOut()
    -- 必须关闭
    -- MoveEnd();
    self._switchInOrOut = false
    self._character.FSM:TryTransitionTo(PlayerState.Switch, self._switchInOrOut)
    local time = self._character.AnimationAdapter:GetAnimationClipLength("TransformToCat")
    return time
end


function PlayerController:Attack()
    self._character.FSM:TryTransitionTo(PlayerState.Attack)
end



function PlayerController:SlowDownMoveInput(val)
    return val.normalized / 1000
end



function PlayerController:IsRunTurnBackInput(lastMoveInput, currentMoveInput)
    -- 如果两次输入反向，则认为是急转输入（夹角大于阈值即认为是反向）
    local angle = Vector3.Angle(lastMoveInput, currentMoveInput)
    if angle > self.runTurnBackAngleThreshold then
        --print("180 turn -1-")
        return true
    end
    
    -- 如果两次输入的变化量，和第一次的输入反向，并且长度大于阈值，则认为是急转输入
    local deltaDirection = currentMoveInput - lastMoveInput
    local angle2 = Vector3.Angle(lastMoveInput, deltaDirection)

    local ret = angle2 > self.runTurnBackAngleThreshold 
                and (deltaDirection.sqrMagnitude > self.runTurnBackDistanceThreshold * self.runTurnBackDistanceThreshold)
    if ret then 
        --print("180 turn -2-")
    end 
    return ret
end



function PlayerController:IdleEnterState(fsm, selfState, fromState, param)
    --Debug.Log( "human -- Idle EnterState" );
    -- self._character.Animator.CrossFadeInFixedTime(AnimatorHash.Idle, 0.1f);
    self.playerState = PlayerState.Idle
    self._idleTimer = 0
end


function PlayerController:IdleUpdate(fsm, selfState, deltaTime)
    if self._character.AnimationAdapter:GetCurrentAnimatorStateInfo(0):IsName("Idle") then
        self._idleTimer = self._idleTimer + Time.deltaTime
        if self._idleTimer > 0.5 then
            -- 处于idle状态了
            self._idleMotionTimer = self._idleMotionTimer + Time.deltaTime
            if self._idleMotionTimer > self.idleMotionInterval then
                self._idleMotionTimer = 0
                local randomIndex = Random.Range(0, 2)
                self._character.AnimationAdapter:CrossFadeInFixedTime(AnimatorHash.IdleMotions[randomIndex], 0.6)
            end
        end
    else
        self._idleTimer = 0
    end
end


function PlayerController:MoveEnterState(fsm, selfState, fromState, param)
    self.playerState = PlayerState.Move
    self._character.AnimationAdapter:CrossFadeInFixedTime(AnimatorHash.Locomotion, 0.1)
end



function PlayerController:MoveUpdate(fsm, selfState, deltaTime)
    --print("hasTurnBack = " .. tostring(self.hasTurnBack))
    if self.hasTurnBack
        and self:IsRunTurnBackInput(self._lastMoveInput, self._moveDir)
        and not self._runTurnBacking
        and self._forwardValue > self.runValue -- !!! 会导致 180转身 很难发出来
    then
        self._runTurnBacking = true
        self._character:StopTurning()
        self._character.useRootMotionRotate = true
        local type = self._character.AnimationAdapter.animationSystemType
        if type == AnimationSystemType.Animator then
            if self._character.AnimationAdapter:GetFloat(AnimatorHash.RunStopValue) < 0.5 then
                --print("tt -1-")
                self._character.AnimationAdapter:CrossFadeInFixedTime(AnimatorHash.RunTurnBackL, 0.1)
            else
                --print("tt -2-")
                self._character.AnimationAdapter:CrossFadeInFixedTime(AnimatorHash.RunTurnBackR, 0.1)
            end
        else
            --print("tt -3-")
            self._character.AnimationAdapter:CrossFadeByTag("RunTurn180")
        end
    else
        if self._runTurnBacking then
            if self._character.AnimationAdapter:GetFloat(AnimatorHash.RunTurnBackEnd) > 0 then
                -- 急转结束
                self._runTurnBacking = false
                self._character.useRootMotionRotate = false
                
                if self._hasMoveInput then
                    -- 急转结束直接跑起来
                    local type = self._character.AnimationAdapter.animationSystemType
                    if type == AnimationSystemType.Animator or type == AnimationSystemType.AnimationManager then
                        self._forwardValue = 1
                        self._character.AnimationAdapter:CrossFadeInFixedTime(AnimatorHash.Locomotion, 0.1)
                    else
                        self._forwardValue = 1
                        self._character.AnimationAdapter:CrossFadeUsePoseMatching(AnimatorHash.Locomotion, "Run")
                    end
                    -- 急转结束时不清除急转之前的速度
                else
                    self._forwardValue = 0
                    self._character.AnimationAdapter:CrossFadeInFixedTime(AnimatorHash.Idle, 0.1)
                    fsm:TryTransitionTo(PlayerState.Idle)
                end
            end
        else
            local isFightWall = self._character:DetectFightWall()
            if isFightWall then
                -- 撞墙的时候就停下移动的动画
                self._forwardValue = Mathf.Lerp(self._forwardValue, 0, 0.2)
            else
                self._forwardValue = Mathf.Lerp(self._forwardValue, self._moveInput.magnitude, 1 - Mathf.Exp(-self.forwardAxisSharpness * Time.deltaTime))
                --self._forwardValue = Mathf.Clamp01( KTool.Remap( 0, 0.95, 0, 1, self._forwardValue ) )
                --print(" _moveInput.magnitude = " .. tostring(self._moveInput.magnitude) )
            end


            self:UpdateFootStepState( self._forwardValue ) -- 在 animator set 前调用

            self._character.AnimationAdapter:SetFloat(AnimatorHash.Forward, self._forwardValue )
            --self._character.AnimationAdapter:SetFloat(AnimatorHash.Forward, self._forwardValue, 0.3, 0.2 )
            self._character:SmoothDampRotateScaling(self._moveDir, self.rotateTimeMax)
        end
    end
end



function PlayerController:MoveExitState(fsm, selfState, toState, param)
    if (self._runTurnBacking) then
        -- 强行打断急转
        self._runTurnBacking = false
        self._character.useRootMotionRotate = false
        self._forwardValue = 0
    else
        if (self._forwardValue > self.runValue and self.hasRunStop) then
            -- 跑停
            local type = self._character.AnimationAdapter.animationSystemType
            if (type == AnimationSystemType.Animator) then
                if (self._character.AnimationAdapter:GetFloat(AnimatorHash.RunStopValue) < 0.5) then
                    self._character.AnimationAdapter:CrossFadeInFixedTime(AnimatorHash.RunStopL, 0.1)
                else
                    self._character.AnimationAdapter:CrossFadeInFixedTime(AnimatorHash.RunStopR, 0.1)
                end
            else
                -- 目前走这个分支
                self._character.AnimationAdapter:CrossFadeByTag("RunEnd")
            end
        else
            -- 走停
            self._character.AnimationAdapter:CrossFadeInFixedTime(AnimatorHash.Idle, 0.1)
        end
        self._forwardValue = 0
    end

    self:UpdateFootStepState( 0 ) -- to Idle
end



function PlayerController:MoveCanTransitionTo(fsm, selfState, toState, param)
    local toMove = toState.stateId == PlayerState.Move
    if (toMove) then
        return false
    end
    local toIdle = toState.stateId == PlayerState.Idle
    if (toIdle) then
        return not self._runTurnBacking
    end
    return true
end


function PlayerController:SwitchEnterState(fsm, selfState, fromState, param)
    self._stateTimer = 0
    local switchInOrOut = param
    self.playerState = PlayerState.Switch
    
    if switchInOrOut then
        -- 切进
        self._character.useGravity = true
        self._character.AnimationAdapter:CrossFadeInFixedTime(AnimatorHash.FromCat, 0)
    else
        -- 切出
        self._character.useGravity = false
        self._character.AnimationAdapter:CrossFadeInFixedTime(AnimatorHash.ToCat, 0.1)
    end
end


function PlayerController:SwitchUpdate(fsm, selfState, deltaTime)
    if self._stateTimer < self._stateTimerMax then
        self._stateTimer = self._stateTimer + deltaTime
        return
    end
    
    if not self._character.AnimationAdapter:IsInTransition(0) and self._character.AnimationAdapter:GetCurrentAnimatorStateInfo(0):IsName("Idle") then
        fsm:TryTransitionTo(PlayerState.Idle)
    end
end



function PlayerController:SwitchCanTransitionTo(fsm, selfState, toState, param)
    local toIdle = toState.stateId == PlayerState.Idle
    return toIdle
end


function PlayerController:AttackEnterState(fsm, selfState, fromState, param)
    self.playerState = PlayerState.Attack
    self._stateTimer = 0
    self._attackCanInterrupt = false
    self._character.AnimationAdapter:CrossFadeInFixedTime(AnimatorHash.MeleeAttack, 0.06)
end


function PlayerController:AttackUpdate(fsm, selfState, deltaTime)
    if self._stateTimer < self._stateTimerMax then
        self._stateTimer = self._stateTimer + deltaTime
        return
    end
    if not self._character.AnimationAdapter:IsInTransition(0) and self._character.AnimationAdapter:GetCurrentAnimatorStateInfo(0):IsName("Idle") then
        fsm:TryTransitionTo(PlayerState.Idle)
    end
    
    if self._character.AnimationAdapter:GetFloat(AnimatorHash.CanInterrupt) > 0.5 then
        self._attackCanInterrupt = true
    end
end



function PlayerController:AttackCanTransitionTo(fsm, selfState, toState, param)
    local toIdle = toState.stateId == PlayerState.Idle
    if toIdle then
        return true
    end
    local toAttack = toState.stateId == PlayerState.Attack
    local toMove = toState.stateId == PlayerState.Move
    if toAttack or toMove then
        return self._attackCanInterrupt
    end
    
    return toState.stateId > selfState.stateId
end



function PlayerController:UpdateFootStepState( forwardValue_ )

    self.currentFootStepState = (forwardValue_ < 0.01) and FootStepState.Idle or 
        ( (forwardValue_ < 0.8) and FootStepState.Walk or FootStepState.Run )

    -- 发生切换时:
    if self.currentFootStepState ~= self.oldFootStepState then 
        

        for _,func in pairs(self.WhenPlayerMoveStateChangeds) do 
            assert( isNotNull(func) )
            func( self.currentFootStepState, self.oldFootStepState )
        end

        self.oldFootStepState = self.currentFootStepState
    end
end



function PlayerController:WhenCallEvent_Effect( name )


    if name == "Foot" then 
        --print( "触发动画 event Foot" )

        -- 播放 人物 走路/跑步 的声音:
        if (DreamSpaceStates.floorMaterial == DreamSpaceStates.FloorMaterials.Default) then
            DreamSpaceSounds.Play( DreamSpaceSounds.sfx.humanWalkMetal )
        else
            DreamSpaceSounds.Play( DreamSpaceSounds.sfx.humanWalkGlass )
        end

    end
    
end



return PlayerController
